import { useForm } from "react-hook-form"
import Input from "../../Input/Input";
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Boton from '../../Boton/Boton'
import './NuevaMarca.css'
import { useState } from 'react'
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";


export default function NuevaMarca({ onGuardar, actualizarCategoriasYMarcas }) {

  //Recupero informacion del usuario logueado
  const { token } = useValidarSesion(); // obtener el token desde Zustand

  /////// HOOK FORM
  const { register, handleSubmit, formState: { errors }, reset } = useForm({

  });



  /////// CREACION POST DE MARCA
  const onSubmit = async (data) => {
    setCargando(true);
    try {
  const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/marca`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(data),
      });

      // Intentamos leer siempre la respuesta (aunque haya error)
      const dataRespuestaMarca = await respuesta.json().catch(() => ({}));

      if (respuesta.ok) {
        reset();
        toast.success("Marca creada correctamente.", { className: "__toaster_success" });
        {actualizarCategoriasYMarcas && actualizarCategoriasYMarcas.current();}
        onGuardar();
        console.log('Marca creada:', dataRespuestaMarca);
        return;
      } else {
        const mensajeError = dataRespuestaMarca?.error || "Error al crear la marca.";
        toast.error(mensajeError, { className: "__toaster_error" });
        return;
      }
    } catch (error) {
      console.error('Error en la solicitud:', error);
      toast.error("Error inesperado al crear la marca.", { className: "__toaster_error" });
    } finally {
      setCargando(false);
    }
  };


  /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
  const [cargando, setCargando] = useState(false);

  ////// LAYOUT
  return (
    <>
      {cargando && <div className='__cargando_fondo'><div className="__cargando"></div> </div>}
      <form onSubmit={handleSubmit(onSubmit)} className="__form_nueva_marca_categoria">
        <Tarjeta descripcion="Nueva Marca" forid="marca" mensajeError={errors.nombre_marca?.message} >
          <Input
            tipo="text"
            id="marca"
            {...register("nombre_marca", { required: { value: true, message: "Ingrese nueva Marca" } })}
          />
        </Tarjeta>
        <Boton descripcion='Crear' habilitado submit></Boton>
      </form>
    </>

  )

}